export const topbarMarkup = `<a class="skip" href="#content">Skip to content</a><header class="topbar"><a class="brand" href="/dashboard">AntSeed</a><nav aria-label="Workspace"><a href="/dashboard">Overview</a><a href="/outreach">CRM</a><a href="/approvals" id="approvals-link" hidden>Approvals</a><a href="/work">My tasks</a><a href="/team" id="access-link" hidden>Access</a><a href="/connections" id="connections-link" hidden>Connections</a></nav><div class="identity"><span id="identity">Loading account…</span><button id="logout" type="button">Sign out</button></div></header>`;

export const roleLabels = { admin: 'Admin', crm_manager: 'CRM manager', member: 'Member', viewer: 'Viewer' } as const;

export const topbarScript = String.raw`
const roleLabels=${JSON.stringify(roleLabels)};
const permissionList=[['Read the dashboard, CRM, Work and team tasks',['admin','crm_manager','member','viewer']],['Create, edit, move and delete your own tasks',['admin','crm_manager','member']],['Move CRM cards between stages',['admin','crm_manager']],['Move Work tickets between lanes',['admin','crm_manager']],['Approve or reject AI suggestions in Approvals',['admin','crm_manager']],['Invite people and change roles',['admin']],['Manage connections and approve chat intake',['admin']]];
function permissionsDialog(member){let d=document.getElementById('permissions');if(!d){d=document.createElement('dialog');d.id='permissions';d.className='perm-dialog';d.setAttribute('aria-labelledby','permissions-title');document.body.append(d);d.addEventListener('click',e=>{if(e.target===d)d.close();});}
 const h=document.createElement('h2');h.id='permissions-title';h.textContent='Permissions · '+(member.display_name||member.email)+' · '+(roleLabels[member.role]||member.role);const note=document.createElement('p');note.textContent='Read only. Permissions come from the role; change it in the Members list. Nobody, including admins, can edit another person’s tasks.';
 const ul=document.createElement('ul');for(const [text,allowed] of permissionList){const on=allowed.includes(member.role),li=document.createElement('li'),mark=document.createElement('span'),label=document.createElement('span');li.dataset.on=String(on);mark.className='mark';mark.setAttribute('aria-hidden','true');mark.textContent=on?'✓':'–';label.textContent=text+(on?'':' (not allowed)');li.append(mark,label);ul.append(li);}
 const form=document.createElement('form'),close=document.createElement('button');form.method='dialog';close.textContent='Close';close.className='primary';form.append(close);d.replaceChildren(h,note,ul,form);return d;}
function mountTopbar(member){const who=document.getElementById('identity');who.replaceChildren();const name=document.createElement('strong');name.textContent=member.display_name||member.email;const badge=document.createElement('span');badge.className='role-badge';badge.textContent=roleLabels[member.role]||member.role;who.append(name,badge);
 document.getElementById('access-link').hidden=document.getElementById('connections-link').hidden=member.role!=='admin';document.getElementById('approvals-link').hidden=!['admin','crm_manager'].includes(member.role);
 for(const a of document.querySelectorAll('.topbar nav a'))if(a.getAttribute('href')===location.pathname)a.setAttribute('aria-current','page');
 document.getElementById('logout').onclick=async()=>{document.getElementById('logout').disabled=true;try{await fetch('/auth/logout',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});}finally{location.assign('/login');}};}`;

