export const loginPage = String.raw`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sign in · AntSeed</title><style>${styles}</style></head><body><main class="login" id="content"><div class="brand">AntSeed</div><h1 id="heading">Sign in to your workspace</h1><p class="muted" id="lede">CRM pipeline, your tasks, and a shared view of the team's work.</p>
<form id="login" novalidate><label>Email<input name="email" type="email" autocomplete="username" required maxlength="320" autofocus></label><label>Password<input name="password" type="password" autocomplete="current-password" required maxlength="1024" aria-describedby="password-hint"></label><p class="muted hint" id="password-hint" hidden>Use at least 12 characters.</p><label class="show"><input type="checkbox" id="show"> Show password</label><button type="submit" class="primary" id="submit">Sign in</button></form>
<button class="switch" id="switch" type="button">First time here? Set up your invited account</button><p class="muted" id="help">Access is managed by your workspace administrator. Ask them to add your email if you can't sign in.</p><p id="message" class="notice" role="status" hidden></p></main><script>
const form=document.getElementById('login'),message=document.getElementById('message'),submit=document.getElementById('submit');let signup=false,busy=false;
const say=(text,error=false)=>{message.hidden=!text;message.dataset.error=String(error);message.setAttribute('role',error?'alert':'status');message.textContent=text;};
function setMode(next){signup=next;document.getElementById('heading').textContent=signup?'Set up your invited account':'Sign in to your workspace';document.getElementById('lede').textContent=signup?'Use the email your administrator invited. You will confirm it from your inbox before you sign in.':"CRM pipeline, your tasks, and a shared view of the team's work.";submit.textContent=signup?'Create account':'Sign in';form.elements.password.autocomplete=signup?'new-password':'current-password';document.getElementById('password-hint').hidden=!signup;document.getElementById('switch').textContent=signup?'Already registered? Sign in':'First time here? Set up your invited account';document.getElementById('help').hidden=signup;}
document.getElementById('switch').onclick=()=>{setMode(!signup);say('');};
document.getElementById('show').onchange=e=>{form.elements.password.type=e.target.checked?'text':'password';};
form.onsubmit=async e=>{e.preventDefault();if(busy)return;const email=form.elements.email.value.trim(),password=form.elements.password.value;
 if(!email||!form.elements.email.checkValidity()){say('Enter a valid email address.',true);form.elements.email.focus();return;}
 if(!password){say('Enter your password.',true);form.elements.password.focus();return;}
 if(signup&&password.length<12){say('Choose a password with at least 12 characters.',true);form.elements.password.focus();return;}
 busy=true;submit.disabled=true;say(signup?'Creating your account…':'Signing in…');
 try{const response=await fetch(signup?'/auth/signup':'/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email,password})});let value={};try{value=await response.json();}catch{}
  if(!response.ok)throw Error(value.error?.message||(signup?'Could not create the account. Try again.':'Could not sign in. Check your email and password.'));
  form.elements.password.value='';if(signup){setMode(false);say(value.message||'Check your email to confirm your account, then sign in.');}else location.assign('/dashboard');}
 catch(error){say(error.message==='Failed to fetch'?'Could not reach the server. Check your connection and try again.':error.message,true);}
 finally{busy=false;submit.disabled=false;}};
fetch('/auth/config').then(r=>r.json()).then(c=>{if(!c.configured){say('Workspace sign-in is being configured. Please check back shortly.',true);submit.disabled=true;document.getElementById('switch').hidden=true;}}).catch(()=>say('Could not reach sign-in. Reload to try again.',true));
</script></body></html>`;

export const workspacePage = String.raw`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Workspace · AntSeed</title><style>${styles}</style></head><body><main>
${topbarMarkup}
<div class="heading" id="content" tabindex="-1"><div><h1><span id="title">Workspace</span><span id="mode-tag" class="view-only" hidden>View only</span></h1><p id="description" class="muted">Loading…</p></div><div class="actions" style="margin:0"><a id="crm-link" class="button" href="/outreach" hidden>Open CRM</a><button id="create-task" class="primary" type="button" hidden aria-controls="task-editor" aria-expanded="false">New task</button></div></div>
<p id="notice" class="notice" role="status" aria-live="polite">Loading your workspace…</p><dl id="summary" class="summary" aria-label="Workspace summary" hidden></dl>
<section class="editor" id="task-editor" aria-labelledby="editor-title" hidden><h2 id="editor-title">New task</h2><p class="muted">Tasks you create are yours. Teammates can read them but cannot change them.</p><form id="new-task"><label>Task<input name="title" required maxlength="500" placeholder="What needs to happen?"></label><label>Description<textarea name="description" maxlength="20000" placeholder="Add context or a useful link"></textarea></label><div class="field-row"><label>Lane<select name="lane"></select></label><label>Due date<input name="dueDate" type="date"></label></div><div class="actions"><button type="submit" class="primary">Create task</button><button type="button" id="cancel-task">Cancel</button></div></form></section>
<section id="approvals" hidden><div class="toolbar"><div class="seg scroll" id="queue-tabs" role="group" aria-label="Approval queues"></div><button id="queue-refresh" type="button">Refresh</button></div><div id="bulk" class="bulk" hidden></div><div id="queue" class="queue" aria-live="polite"></div></section>
<section id="team" hidden><h2 id="members-title">Members <span class="count" id="member-count">0</span></h2><div id="members" class="member-list" role="list" aria-labelledby="members-title"></div><form id="invite" class="editor" novalidate><h2>Give workspace access</h2><p class="muted">No email is sent. The person creates their account with this address from the sign-in page.</p><div class="field-row"><label>Email<input name="email" type="email" required maxlength="320" autocomplete="off"></label><label>Name<input name="name" maxlength="200" autocomplete="off"></label></div><div class="field-row"><label>Role<select name="role"><option value="member">Member</option><option value="crm_manager">CRM manager</option><option value="viewer">Viewer</option><option value="admin">Admin</option></select></label><label><span>Telegram user ID <span class="muted" style="font-weight:400">(optional)</span></span><input name="telegram" inputmode="numeric" pattern="[1-9][0-9]{0,17}" maxlength="18" autocomplete="off" aria-describedby="telegram-help"></label></div><p class="muted" id="telegram-help">Only needed for CRM managers who approve AI suggestions in Telegram. Use the numeric ID, not a username.</p><div class="actions"><button class="primary" type="submit">Give access</button><span id="invite-result" class="muted" role="status"></span><button type="button" id="copy-link" hidden>Copy sign-in link</button></div></form>
<details class="roles"><summary>What each role can do</summary><dl><dt>Admin</dt><dd>Invites people, sets roles, manages CRM and connections.</dd><dt>CRM manager</dt><dd>Moves CRM cards. Also keeps their own tasks.</dd><dt>Member</dt><dd>Keeps their own tasks. Reads everything else.</dd><dt>Viewer</dt><dd>Reads the shared dashboard. Cannot change anything.</dd></dl><p class="muted">Nobody, including admins, can edit another person's tasks.</p></details>
</section>
<div id="toolbar" class="toolbar"><div class="seg" id="view" role="group" aria-label="Dashboard view" hidden><button type="button" data-view="crm" aria-pressed="true">CRM pipeline</button><button type="button" data-view="team" aria-pressed="false">Team tasks</button><button type="button" data-view="crm-work" aria-pressed="false">CRM Work</button></div><label id="scope-label" hidden>Show<select id="scope"><option value="mine">My tasks</option><option value="team">All team tasks</option><option value="crm-work">CRM Work tickets</option></select></label><label>Search loaded cards<input id="search" type="search" placeholder="Task, company or person" autocomplete="off"></label><button id="refresh" type="button">Refresh</button></div><nav id="stage-nav" class="stage-nav" aria-label="Jump to column"></nav><div id="board" class="board" aria-label="Board"></div><button id="more" type="button" hidden>Load more</button>

</main><script>
${topbarScript}
${detailPanelScript}
let ticketPanel=null;
const lanes=${JSON.stringify(LANES)},stages=${JSON.stringify(SALES_STAGES)};
const el=id=>document.getElementById(id);
const node=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
const mode=location.pathname==='/work'?'work':location.pathname==='/team'?'team':location.pathname==='/approvals'?'approvals':'dashboard';
const feeds={},sources={crm:'/api/outreach/relationships?limit=100',team:'/api/board/tasks?scope=team&limit=200',mine:'/api/board/tasks?scope=mine&limit=200','crm-work':'/api/board/work?limit=100'};
let member=null,source=mode==='dashboard'?'crm':'mine',loading=false,openId=null,creationKey=crypto.randomUUID();
const feed=()=>feeds[source]||(feeds[source]={rows:[],cursor:null,loaded:false});
const json=(method,body)=>({method,headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});
async function api(path,options){let response;try{response=await fetch(path,{cache:'no-store',credentials:'same-origin',...options});}catch{throw Error('Could not reach the server. Check your connection and try again.');}
 let data=null;try{data=await response.json();}catch{}
 if(response.status===401){location.assign('/login');throw Error('Your session ended. Sign in again.');}
 if(!response.ok){const error=Error(data?.error?.message||'Request failed. Try again.');error.status=response.status;throw error;}
 if(data===null)throw Error('The server returned an invalid response. Try again.');return data;}
function notice(text,error=false){const n=el('notice');n.textContent=text;n.dataset.error=String(error);n.setAttribute('role',error?'alert':'status');}
const today=()=>new Date().toLocaleDateString('en-CA');
const day=value=>{if(!value)return null;const d=new Date(String(value).slice(0,10)+'T00:00:00');return Number.isNaN(d.valueOf())?null:d.toLocaleDateString(undefined,{day:'numeric',month:'short',year:'numeric'});};
const stamp=value=>{if(!value)return 'Source date unknown';const d=new Date(value);return Number.isNaN(d.valueOf())?'Source date unknown':d.toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'});};
const stageLabel=id=>stages.find(s=>s.id===id)?.label||'No stage';
function laneOptions(select,value){select.replaceChildren();for(const lane of lanes){const o=node('option',lane);o.value=lane;select.append(o);}select.value=value||lanes[0];}
const isLate=task=>task.due_date&&String(task.due_date).slice(0,10)<today()&&!['Completed','Archived'].includes(task.lane);

function taskCard(task){const legacy=source==='crm-work'||task.kind==='work',card=node('article',undefined,'task'),button=node('button',undefined,'ticket-open'),meta=node('div',undefined,'meta');card.dataset.id=task.id;button.type='button';button.setAttribute('aria-haspopup','dialog');
 const title=task.title||task.nextAction||task.summary||'Work action';if(task.company)button.append(node('p',task.company,'company'));button.append(node('h3',title));const text=task.description||(legacy?task.summary:'');if(text&&text!==title)button.append(node('p',text.length>180?text.slice(0,180)+'…':text,'muted'));
 if(legacy){meta.append(node('span','CRM Work','badge'));if(task.owner_name)meta.append(node('span',task.owner_id===member.id?'You':task.owner_name,'badge'));}else if(source!=='mine')meta.append(node('span',task.owner_id===member.id?'You':(task.owner_name||'Team member'),task.owner_id===member.id?'badge you':'badge'));
 const due=day(task.due_date||task.followUpAt);if(due)meta.append(node('span','Due '+due,'badge'));if(!legacy&&isLate(task))meta.append(node('span','Overdue','badge late'));button.append(meta);button.onclick=()=>void ticketPanel.open({kind:legacy?'work':'personal',id:task.id,title});card.append(button);return card;}
function crmCard(r){const card=node('article',undefined,'task'),button=node('button',undefined,'ticket-open'),meta=node('div',undefined,'meta');card.dataset.id=r.id;button.type='button';button.setAttribute('aria-haspopup','dialog');button.append(node('h3',r.displayName));if(r.nextStep)button.append(node('p',r.nextStep,'muted'));meta.append(node('span','Accepted','badge you'),node('span',r.sourceCount+' source'+(r.sourceCount===1?'':'s'),'badge'));if(r.pendingSourceCount)meta.append(node('span',r.pendingSourceCount+' pending','badge warn'));button.append(meta,node('p',stamp(r.latestSourceAt),'muted'));button.onclick=()=>void ticketPanel.open({kind:'crm',id:r.id,title:r.displayName});card.append(button);return card;}

const isWork=row=>source==='crm-work'||row.kind==='work';
const movable=row=>source==='crm'||isWork(row)?canReview():member.role!=='viewer'&&row.owner_id===member.id;
let dragging=null,moving=false;
function enableDrag(card,row){if(!movable(row))return;card.draggable=true;card.classList.add('movable');
 card.ondragstart=e=>{if(loading||moving){e.preventDefault();return;}dragging=row;e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',row.id);card.classList.add('dragging');};
 card.ondragend=()=>{dragging=null;card.classList.remove('dragging');for(const c of el('board').children)c.classList.remove('drop');};}
async function moveCard(row,target){const crm=source==='crm',from=crm?row.acceptedStage:row.lane;if(moving||from===target)return;moving=true;
 const name=row.displayName||row.title||row.nextAction||row.summary||'Card',label=crm?stageLabel(target):target,reason='Moved by drag and drop',idempotencyKey=crypto.randomUUID();
 if(crm)row.acceptedStage=target;else row.lane=target;render(true);notice('Moving “'+name+'” to '+label+'…');
 try{
  if(crm)await api('/api/board/crm/'+row.id+'/move',json('POST',{targetStage:target,expectedEvidenceRevision:row.evidenceRevision,idempotencyKey,reason}));
  else if(isWork(row))await api('/api/board/work/'+row.id+'/move',json('POST',{targetLane:target,expectedStageVersion:row.stageVersion??row.version,idempotencyKey,reason}));
  else await api('/api/board/tasks/'+row.id,json('PATCH',{title:row.title,description:row.description,lane:target,dueDate:row.due_date?String(row.due_date).slice(0,10):null,expectedVersion:row.version}));
  for(const [key,f] of Object.entries(feeds))if(key!==source)f.loaded=false;
  notice('Moved “'+name+'” to '+label+'.');moving=false;await load(true,true);if(mode==='dashboard')await loadSummary();}
 catch(error){if(crm)row.acceptedStage=from;else row.lane=from;render(true);notice(error.message+(error.status===409?' The board was refreshed.':''),true);moving=false;if(error.status===409)await load(true,true);}
 finally{moving=false;}}

function visibleRows(){const q=el('search').value.trim().toLowerCase();return feed().rows.filter(row=>!q||[row.title,row.company,row.summary,row.nextAction,row.description,row.displayName,row.owner_name].some(v=>String(v||'').toLowerCase().includes(q)));}
const byDue=(a,b)=>String(a.due_date||'9999').localeCompare(String(b.due_date||'9999'))||String(a.title||'').localeCompare(String(b.title||''));
function render(keepScroll){const f=feed(),q=el('search').value.trim(),rows=visibleRows(),crm=source==='crm',columns=crm?stages.map(s=>[s.id,s.label]):lanes.map(l=>[l,l]),scroll=el('board').scrollLeft;
 el('board').replaceChildren();el('stage-nav').replaceChildren();el('board').classList.toggle('crm',crm);el('board').setAttribute('aria-label',crm?'CRM pipeline':source==='mine'?'My tasks by lane':'Tasks by lane');el('board').setAttribute('aria-busy',String(!f.loaded));
 for(const [id,label] of columns){const column=node('section',undefined,'column');column.id='col-'+id.replaceAll(' ','-');column.tabIndex=-1;column.setAttribute('aria-labelledby',column.id+'-h');column.ondragover=e=>{if(!dragging||!f.loaded)return;e.preventDefault();e.dataTransfer.dropEffect='move';column.classList.add('drop');};column.ondragleave=e=>{if(!column.contains(e.relatedTarget))column.classList.remove('drop');};column.ondrop=e=>{e.preventDefault();column.classList.remove('drop');const r=dragging;dragging=null;if(r)void moveCard(r,id);};
  const members=rows.filter(row=>(crm?row.acceptedStage:row.lane)===id);if(!crm)members.sort(byDue);
  const h=node('h2',label);h.id=column.id+'-h';h.append(node('span',f.loaded?String(members.length):'…','count'));column.append(h);
  if(!f.loaded){column.append(node('div',undefined,'skeleton'),node('div',undefined,'skeleton'));}
  else{for(const row of members){const card=crm?crmCard(row):taskCard(row);enableDrag(card,row);column.append(card);}if(!members.length)column.append(node('p',q?'No matches in this '+(crm?'stage':'lane')+'.':crm?(id==='won'?'No accepted deals yet.':id==='archived'?'Nothing archived yet.':'No accepted relationships in this stage.'):source==='mine'?(id===lanes[0]&&member.role!=='viewer'?'Nothing here yet. Use New task to add one.':'None of your tasks are here.'):'No tasks in this lane.','empty'));}
  el('board').append(column);const jump=node('button');jump.type='button';jump.append(document.createTextNode(label),node('span',f.loaded?String(members.length):'','n'));jump.onclick=()=>{column.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'nearest',inline:'start'});column.focus({preventScroll:true});};el('stage-nav').append(jump);}
 if(keepScroll)el('board').scrollLeft=scroll;if(openId){const open=el('board').querySelector('[data-id="'+openId+'"]');openId=null;if(open){open.querySelector('.ticket-open')?.click();}}el('more').hidden=!f.cursor;}
const messages={get crm(){return canReview()?'Open a relationship to inspect sources or move its stage.':'Open a relationship to inspect its details and sources.';},team:'Open a task to see its details. Each person can change only their own tasks.',mine:'Your personal and assigned CRM Work tasks. Open a card to see its details or move it to another swimlane.','crm-work':'Open a Work ticket for its conversation, evidence, and history.'};
async function load(reset,quiet){if(loading)return;const key=source,f=feed();loading=true;el('refresh').disabled=el('more').disabled=true;if(reset&&!quiet){f.rows=[];f.cursor=null;f.loaded=false;render();}
 try{const result=await api(sources[key]+(!reset&&f.cursor?'&cursor='+encodeURIComponent(f.cursor):''));const seen=new Map([...(reset?[]:f.rows),...result.items.filter(r=>key!=='crm'||r.acceptedStage)].map(r=>[r.id,r]));f.rows=[...seen.values()];f.cursor=result.nextCursor;f.loaded=true;if(key===source){render(quiet);if(!quiet)notice(messages[source]+(f.cursor?' More are available.':''));}}
 catch(error){f.loaded=true;if(key===source){render();notice(error.message,true);}}finally{loading=false;el('refresh').disabled=el('more').disabled=false;}}
async function loadSummary(){try{const s=await api('/api/board/summary'),n=v=>v===undefined||v===null?'—':String(v),c=s.crm||{};
 const values=[['Active tasks',s.active_tasks],['Overdue',s.overdue_tasks],['Companies in talks',c.companiesInTalks],['Active opportunities',c.activeOpportunities],['Follow-ups due',c.followUpsDue],...(canReview()?[['Pending approvals',c.pendingApprovals]]:[]),['Deals won',c.dealsWon]];
 el('summary').replaceChildren(...values.map(([label,value])=>{const item=node('div');item.append(node('dd',n(value)),node('dt',label));return item;}));el('summary').hidden=false;}catch(error){notice(error.message,true);}}

function memberRow(m){const row=node('div',undefined,'member'),who=node('div',undefined,'who'),name=node('strong',m.display_name||m.email);row.setAttribute('role','listitem');row.dataset.disabled=String(!m.enabled);
 const info=node('button','i','info-btn');info.type='button';info.title='View permissions for '+(m.display_name||m.email);info.setAttribute('aria-label',info.title);info.setAttribute('aria-haspopup','dialog');info.onclick=()=>permissionsDialog(m).showModal();who.append(name,info);if(m.id===member.id)who.append(node('span','You','role-badge'));if(!m.enabled)who.append(node('span','Access off','role-badge'));who.append(node('p',m.email,'muted'));
 const rl=node('label','Role'),role=node('select');for(const [value,text] of Object.entries(roleLabels)){const o=node('option',text);o.value=value;role.append(o);}role.value=m.role;role.setAttribute('aria-label','Role for '+m.email);rl.append(role);
 const tl=node('label','Telegram user ID'),tg=node('input');tg.value=m.telegram_user_id||'';tg.inputMode='numeric';tg.maxLength=18;tg.setAttribute('aria-label','Telegram user ID for '+m.email);tg.placeholder='Not linked';tl.append(tg);
 const el_=node('label',undefined,'enabled'),enabled=node('input');enabled.type='checkbox';enabled.checked=m.enabled;el_.append(enabled,document.createTextNode('Access on'));enabled.setAttribute('aria-label','Access on for '+m.email);
 const save=node('button','Save'),status=node('p','','muted status');status.setAttribute('role','status');save.type='button';
 const hint=()=>{const needs=['admin','crm_manager'].includes(role.value)&&!tg.value.trim();status.textContent=needs?'No Telegram ID linked. This person cannot approve AI suggestions in Telegram.':'';};
 const dirty=()=>save.disabled=role.value===m.role&&enabled.checked===m.enabled&&tg.value.trim()===(m.telegram_user_id||'');
 for(const f of [role,tg,enabled])f.addEventListener('input',()=>{dirty();hint();});dirty();hint();
 save.onclick=async()=>{const id=tg.value.trim();if(id&&!/^[1-9][0-9]{0,17}$/.test(id)){status.textContent='Telegram user ID must be a number, for example 123456789.';tg.focus();return;}
  save.disabled=true;status.textContent='Saving…';try{const updated=await api('/api/workspace/members/'+m.id,json('PATCH',{role:role.value,enabled:enabled.checked,expectedVersion:m.version,telegramUserId:id||null}));Object.assign(m,updated);if(m.id===member.id)member=Object.assign(member,{role:m.role});row.replaceWith(memberRow(m));notice('Updated '+(m.display_name||m.email)+': '+roleLabels[m.role]+(m.enabled?'':', access off')+'.');}catch(error){status.textContent=error.message;dirty();}};
 row.append(who,rl,tl,el_,save,status);return row;}
async function loadMembers(){const data=await api('/api/workspace/members');el('member-count').textContent=String(data.items.length);el('members').replaceChildren(...data.items.map(memberRow));}

el('search').oninput=()=>render(true);el('refresh').onclick=()=>{void load(true);if(mode==='dashboard')void loadSummary();};el('more').onclick=()=>void load(false);
el('scope').onchange=()=>{source=el('scope').value;openId=null;const f=feed();if(f.loaded)render();else void load(true);if(f.loaded)notice(messages[source]);};
for(const b of el('view').querySelectorAll('button'))b.onclick=()=>{source=b.dataset.view;openId=null;for(const o of el('view').querySelectorAll('button'))o.setAttribute('aria-pressed',String(o===b));const f=feed();if(f.loaded){render();notice(messages[source]);}else void load(true);};
function setEditor(open){el('task-editor').hidden=!open;el('create-task').setAttribute('aria-expanded',String(open));}
laneOptions(el('new-task').elements.lane);el('create-task').onclick=()=>{setEditor(true);el('new-task').elements.title.focus();};el('cancel-task').onclick=()=>{setEditor(false);el('create-task').focus();};
el('new-task').onsubmit=async event=>{event.preventDefault();const f=event.target.elements,button=event.target.querySelector('button[type=submit]');if(!f.title.value.trim()){notice('Give the task a title.',true);f.title.focus();return;}button.disabled=true;
 try{const row=await api('/api/board/tasks',json('POST',{title:f.title.value.trim(),description:f.description.value,lane:f.lane.value,dueDate:f.dueDate.value||null,idempotencyKey:creationKey}));event.target.reset();creationKey=crypto.randomUUID();setEditor(false);
  source='mine';el('scope').value='mine';const mine=feeds.mine||(feeds.mine={rows:[],cursor:null,loaded:false});if(mine.loaded)mine.rows=[{...row,owner_name:member.display_name||member.email,due_date:row.due_date?String(row.due_date).slice(0,10):null},...mine.rows.filter(r=>r.id!==row.id)];else{await load(true);}openId=row.id;render();notice('Created “'+row.title+'” in '+row.lane+'.');}
 catch(error){notice(error.message,true);}finally{button.disabled=false;}};
el('invite').onsubmit=async event=>{event.preventDefault();const f=event.target.elements,button=event.target.querySelector('button[type=submit]'),result=el('invite-result'),tg=f.telegram.value.trim();result.textContent='';el('copy-link').hidden=true;
 if(!f.email.checkValidity()||!f.email.value.trim()){result.textContent='Enter a valid email address.';f.email.focus();return;}
 if(tg&&!/^[1-9][0-9]{0,17}$/.test(tg)){result.textContent='Telegram user ID must be a number.';f.telegram.focus();return;}
 button.disabled=true;try{const email=f.email.value.trim();await api('/api/workspace/members',json('POST',{email,displayName:f.name.value.trim(),role:f.role.value,telegramUserId:tg||null}));event.target.reset();await loadMembers();result.textContent=email+' can now create an account. No email was sent.';el('copy-link').hidden=!navigator.clipboard;notice('Access given to '+email+'.');}
 catch(error){result.textContent=error.message;}finally{button.disabled=false;}};
el('copy-link').onclick=async()=>{try{await navigator.clipboard.writeText(location.origin+'/login');el('invite-result').textContent+=' Sign-in link copied.';el('copy-link').hidden=true;}catch{el('invite-result').textContent='Could not copy. The sign-in page is '+location.origin+'/login';}};

/* ---- Approvals (admin and CRM manager only) ---- */
const canReview=()=>['admin','crm_manager'].includes(member.role);
const Q={placements:{path:'/api/board/approvals/placements?limit=100'},proposals:{path:'/api/board/approvals/proposals?limit=50'},work:{path:'/api/board/approvals/work?limit=50'},intake:{path:'/api/board/approvals/intake?limit=50'}};
for(const q of Object.values(Q))Object.assign(q,{rows:[],cursor:null,loaded:false,error:null,loading:false});
const tabs=[{id:'placement',label:'Initial placement',stores:['placements','proposals']},{id:'changes',label:'CRM changes',stores:['proposals']},{id:'work',label:'Work',stores:['proposals','work']},{id:'intake',label:'Chat intake',stores:['intake'],admin:true}];
let tab='placement';
const isWorkProposal=p=>p.command_kind==='work';
const placementIds=()=>new Set(Q.placements.rows.map(r=>r.id));
const stageProposalFor=id=>Q.proposals.rows.find(p=>(p.command_kind||'stage')==='stage'&&p.relationship_id===id);
function tabItems(id){const ids=placementIds();if(id==='placement')return Q.placements.rows;if(id==='changes')return Q.proposals.rows.filter(p=>!isWorkProposal(p)&&!((p.command_kind||'stage')==='stage'&&ids.has(p.relationship_id)));if(id==='work')return [...Q.proposals.rows.filter(isWorkProposal),...Q.work.rows];return Q.intake.rows;}
function tabCount(t){const more=t.stores.some(n=>Q[n].cursor),loaded=t.stores.every(n=>Q[n].loaded);return loaded?String(tabItems(t.id).length)+(more?'+':''):'…';}
function renderTabs(){const box=el('queue-tabs');box.replaceChildren();for(const t of tabs){if(t.admin&&member.role!=='admin')continue;const b=node('button');b.type='button';b.setAttribute('aria-pressed',String(t.id===tab));b.append(document.createTextNode(t.label),node('span',tabCount(t),'n'));b.onclick=()=>{tab=t.id;renderTabs();renderQueue();box.querySelector('[aria-pressed=true]').focus();};b.onfocus=()=>b.scrollIntoView({inline:'nearest',block:'nearest'});box.append(b);}}
async function loadStore(name,reset){const q=Q[name];if(q.loading)return;q.loading=true;if(reset){q.rows=[];q.cursor=null;q.loaded=false;q.error=null;}
 try{const result=await api(q.path+(!reset&&q.cursor?'&cursor='+encodeURIComponent(q.cursor):''));const seen=new Map([...q.rows,...result.items].map(r=>[r.id,r]));q.rows=[...seen.values()];q.cursor=result.nextCursor;q.loaded=true;q.error=null;}
 catch(error){q.error=error.message;q.loaded=true;}finally{q.loading=false;}renderTabs();renderQueue();}
const loadAll=()=>(notice(''),Promise.all(['placements','proposals','work',...(member.role==='admin'?['intake']:[])].map(n=>loadStore(n,true))));
const dateText=v=>stamp(v).replace('Source date unknown','Date unknown');
const originLabel=o=>o==='manual'?'Requested by a person':o==='historical_policy'?'Historical policy':'AI suggestion';
function proposalLabel(p){const k=p.command_kind||'stage',a=p.command_payload&&p.command_payload.action;return k==='stage'?'Move to '+stageLabel(p.target_stage):k==='work'?'Create Work ticket'+(a?': '+a:''):k==='actions'?'Change AntSeed follow-up':k==='identity'?'Correct company identity':k==='work_actions'?'Correct a Work action or deadline':k==='fact'?'Correct a source fact':'Change request';}
function resolved(card,text){const d=node('p',text,'done');d.tabIndex=-1;card.replaceWith(d);d.focus();}
/* A decision block: optional reason, buttons that disable while saving, explicit conflict handling. */
function decideBlock(card,opts){const box=node('div',undefined,'decide'),label=node('label','Reason (optional)'),reason=node('input'),status=node('p','','muted'),actions=node('div',undefined,'actions'),keys={};
 reason.maxLength=500;reason.placeholder=opts.placeholder||'Add a note for the audit trail';label.append(reason);status.setAttribute('role','status');
 const buttons=[];
 const run=async(action,extra)=>{for(const b of buttons)b.disabled=true;status.textContent='Saving…';keys[action]=keys[action]||crypto.randomUUID();
  try{const message=await opts.run(action,reason.value.trim(),keys[action],extra);resolved(card,message);renderTabs();}
  catch(error){status.textContent=error.message;for(const b of buttons)b.disabled=false;if(error.status===409||error.status===404){notice(error.message+' It may have been decided elsewhere, so the list was refreshed.',true);delete keys[action];void opts.refresh();}}};
 for(const [action,text,cls] of opts.buttons){const b=node('button',text,cls);b.type='button';b.onclick=()=>void run(action);buttons.push(b);actions.append(b);}
 box.append(label,actions,status);if(opts.extra)box.append(opts.extra(run,buttons,status));return box;}
function correctStage(current){return (run,buttons,status)=>{const d=node('details'),s=node('summary','Suggest a different stage'),sel=node('select'),lab=node('label','Stage'),go=node('button','Replace suggestion');go.type='button';for(const st of stages){const o=node('option',st.label);o.value=st.id;sel.append(o);}sel.value=current||'lead';sel.setAttribute('aria-label','Replacement stage');lab.append(sel);go.onclick=()=>{go.disabled=true;void run('correct',sel.value);};buttons.push(go);d.append(s,lab,go,node('p','The replacement stays pending until a reviewer approves it. Nothing is applied.','muted'));return d;};}
function proposalOpts(p,after){const stage=(p.command_kind||'stage')==='stage';
 return {buttons:[['approve','Approve','primary'],['reject','Reject']],refresh:()=>loadStore('proposals',true),
  run:async(action,reason,key,corrected)=>{const body={action,reason:reason||(action==='approve'?'Approved in Approvals':action==='reject'?'Rejected in Approvals':'Corrected in Approvals'),idempotencyKey:key};if(action==='correct')body.correctedStage=corrected;
   await api('/api/board/approvals/proposals/'+p.id+'/decision',json('POST',body));Q.proposals.rows=Q.proposals.rows.filter(x=>x.id!==p.id);
   if(action==='correct'){void loadStore('proposals',true);return 'Replacement suggestion created for '+(p.display_name||'this relationship')+'. It is pending approval; nothing is applied.';}
   if(action==='reject')return 'Rejected: '+proposalLabel(p)+' for '+(p.display_name||'this relationship')+'. Nothing was changed.';
   if(after)after();return stage?'Approved: '+(p.display_name||'this relationship')+' is now in '+stageLabel(p.target_stage)+'.':'Approved: '+proposalLabel(p)+' for '+(p.display_name||'this relationship')+'. Decision recorded.';}};}
const proposalDecision=(card,p,after)=>decideBlock(card,{...proposalOpts(p,after),extra:(p.command_kind||'stage')==='stage'?correctStage(p.target_stage):null});
/* Approve / Reject straight from the collapsed card, with no need to expand it first. */
function quickBar(card,opts){const bar=node('div',undefined,'actions quick'),status=node('p','','muted'),keys={},buttons=[];status.setAttribute('role','status');
 for(const [action,text,cls] of opts.buttons){const b=node('button',text,cls);b.type='button';buttons.push(b);bar.append(b);
  b.onclick=async event=>{event.preventDefault();for(const x of buttons)x.disabled=true;status.textContent='Saving…';keys[action]=keys[action]||crypto.randomUUID();
   try{resolved(card,await opts.run(action,'',keys[action]));renderTabs();}
   catch(error){status.textContent=error.message;for(const x of buttons)x.disabled=false;if(error.status===409||error.status===404){notice(error.message+' It may have been decided elsewhere, so the list was refreshed.',true);delete keys[action];void opts.refresh();}}};}
 bar.append(status);return bar;}
function proposalCard(p,inline){const card=node('details',undefined,'task'),summary=node('summary'),meta=node('div',undefined,'meta'),kind=p.command_kind||'stage';
 summary.append(node('h3',p.display_name||'Relationship'),node('p',proposalLabel(p),'muted'));meta.append(node('span',originLabel(p.origin),'badge'),node('span','Pending approval · not applied','badge warn'),node('span',dateText(p.created_at),'badge'));summary.append(meta,quickBar(card,proposalOpts(p)));card.append(summary);
 const body=node('div',undefined,'body');if(kind==='stage')body.append(node('p','Current stage: '+stageLabel(p.accepted_stage)+'. Proposed: '+stageLabel(p.target_stage)+'.'));
 if(p.reason)body.append(node('p',p.reason,'muted'));
 const pl=p.command_payload||{};if(kind!=='stage'&&Object.keys(pl).length){const d=node('details'),s=node('summary','Proposed change');d.append(s);if(Array.isArray(pl.actions)){const ul=node('ul');for(const a of pl.actions)ul.append(node('li',a.text+(a.localDate?' · due '+a.localDate:'')+(a.state&&a.state!=='open'?' · '+a.state:'')));d.append(ul);}else d.append(node('p',JSON.stringify(pl,null,2).slice(0,4000),'pre'));body.append(d);}
 const context=node('div');body.append(context,proposalDecision(card,p));card.append(body);let requested=false;card.addEventListener('toggle',()=>{if(card.open&&!requested&&p.relationship_id){requested=true;void loadContext({id:p.relationship_id},context);}});return card;}
function sourceBlock(source,pending){const d=node('details',undefined,'source');d.append(node('summary',source.title+' · '+(source.operationalLane||(source.kind==='telegram'?'Telegram conversation':'Email report'))),node('p',(pending?'Pending enrollment · review context only':'Approved source')+' · '+stamp(source.latestSourceAt),'muted'));
 const contacts=node('ul');for(const c of source.contacts||[])contacts.append(node('li',(c.names.join(', ')||c.usernames.join(', ')||'Unnamed contact')+' · '+(c.roles.join(', ')||'Role unknown')+' · '+c.affiliation));d.append(node('h4','Contacts'),contacts.children.length?contacts:node('p','No sourced contacts.','muted'));
 const facts=node('ul');for(const f of source.facts||[])facts.append(node('li',f.text+' · '+(f.actor.displayName||f.actor.party)+' · '+f.state));d.append(node('h4','Tasks, questions and deadlines'),facts.children.length?facts:node('p','No sourced facts.','muted'));
 const ev=node('details');ev.append(node('summary','Source evidence ('+(source.evidence||[]).length+')'));for(const e of source.evidence||[])ev.append(node('p',e.excerpt,'evidence'));d.append(ev);if(source.coverage&&source.coverage.truncated)d.append(node('p','Bounded context shown; more history exists.','muted'));return d;}
async function loadContext(r,target){target.replaceChildren(node('p','Loading source context…','muted'));try{const d=await api('/api/board/approvals/relationships/'+encodeURIComponent(r.id));target.replaceChildren(node('h4','Source context','group'));if(!d.activeSources.length&&!d.pendingSources.length)target.append(node('p','No source context is available.','muted'));for(const s of d.activeSources)target.append(sourceBlock(s,false));for(const s of d.pendingSources)target.append(sourceBlock(s,true));for(const l of d.limits||[])target.append(node('p',l,'muted'));}catch(error){target.replaceChildren(node('p',error.message,'muted'));const again=node('button','Retry');again.type='button';again.onclick=()=>void loadContext(r,target);target.append(again);}}
function placementCard(r){const card=node('details',undefined,'task'),summary=node('summary'),meta=node('div',undefined,'meta'),pending=stageProposalFor(r.id);
 summary.append(node('h3',r.displayName));if(r.nextStep)summary.append(node('p',r.nextStep,'muted'));meta.append(node('span',pending?'AI suggestion pending':'Needs a stage',pending?'badge warn':'badge'),node('span',r.sourceCount+' source'+(r.sourceCount===1?'':'s'),'badge'));if(r.pendingSourceCount)meta.append(node('span',r.pendingSourceCount+' pending','badge warn'));const dropPlacement=()=>{Q.placements.rows=Q.placements.rows.filter(x=>x.id!==r.id);};summary.append(meta,node('p',dateText(r.latestSourceAt),'muted'));if(pending)summary.append(quickBar(card,proposalOpts(pending,dropPlacement)));card.append(summary);
 const body=node('div',undefined,'body'),context=node('div');
 if(pending){const note=node('div',undefined,'proposal-note');note.append(node('p',originLabel(pending.origin)+': move to '+stageLabel(pending.target_stage)+'. Pending approval · not applied.'));if(pending.reason)note.append(node('p',pending.reason,'muted'));body.append(note,proposalDecision(card,pending,dropPlacement));}
 else{const sel=node('select'),lab=node('label','Place in stage');for(const st of stages){const o=node('option',st.label);o.value=st.id;sel.append(o);}lab.append(sel);sel.setAttribute('aria-label','Initial stage');
  body.append(decideBlockPlace(card,r,sel,lab));}
 body.append(context);card.append(body);let requested=false;card.addEventListener('toggle',()=>{if(card.open&&!requested){requested=true;void loadContext(r,context);}});return card;}
function decideBlockPlace(card,r,sel,lab){const box=node('div',undefined,'decide'),reason=node('input'),rl=node('label','Reason (optional)'),go=node('button','Place on CRM board','primary'),status=node('p','','muted'),note=node('p','Saves immediately and moves this card onto the CRM board. No Telegram message is sent.','muted');let key=crypto.randomUUID();
 reason.maxLength=500;reason.placeholder='Add a note for the audit trail';rl.append(reason);go.type='button';status.setAttribute('role','status');
 for(const f of [sel,reason])f.addEventListener('input',()=>{key=crypto.randomUUID();});
 go.onclick=async()=>{go.disabled=true;status.textContent='Placing…';try{await api('/api/board/approvals/relationships/'+r.id+'/place',json('POST',{targetStage:sel.value,expectedEvidenceRevision:r.evidenceRevision,idempotencyKey:key,reason:reason.value.trim()||'Initial placement by a CRM manager'}));Q.placements.rows=Q.placements.rows.filter(x=>x.id!==r.id);resolved(card,r.displayName+' placed in '+stageLabel(sel.value)+'. It now appears on the CRM board.');renderTabs();}
  catch(error){status.textContent=error.message;go.disabled=false;if(error.status===409||error.status===404){notice(error.message+' It may have been decided elsewhere, so the list was refreshed.',true);void loadStore('placements',true);}}};
 box.append(lab,rl,go,note,status);return box;}
function workCard(w){const card=node('details',undefined,'task'),summary=node('summary'),meta=node('div',undefined,'meta');summary.append(node('h3',w.display_name||'Work item'),node('p',w.next_action||'Lane change','muted'));meta.append(node('span',w.source_lane+' → '+w.target_lane,'badge'),node('span','Pending approval · not applied','badge warn'),node('span',dateText(w.created_at),'badge'));const opts={buttons:[['approve','Approve','primary'],['reject','Reject']],refresh:()=>loadStore('work',true),run:async(action,reason,key)=>{await api('/api/board/approvals/work/'+w.id+'/decision',json('POST',{action,reason:reason||(action==='approve'?'Approved in Approvals':'Rejected in Approvals'),idempotencyKey:key}));Q.work.rows=Q.work.rows.filter(x=>x.id!==w.id);return action==='approve'?'Approved: '+w.display_name+' to '+w.target_lane+'. Queued; the board applies the lane change shortly.':'Rejected: '+w.display_name+' stays in '+w.source_lane+'.';}};
 summary.append(meta,quickBar(card,opts));card.append(summary);
 const body=node('div',undefined,'body');if(w.reason)body.append(node('p',w.reason,'muted'));
 body.append(decideBlock(card,opts));card.append(body);return card;}
function intakeCard(i){const card=node('details',undefined,'task'),summary=node('summary'),meta=node('div',undefined,'meta');summary.append(node('h3',i.title||'Untitled chat'));if(i.username)summary.append(node('p','@'+i.username,'muted'));meta.append(node('span',i.kind||'chat','badge'),node('span','Pending admission','badge warn'),node('span',dateText(i.created_at),'badge'));summary.append(meta);card.append(summary);
 const body=node('div',undefined,'body');body.append(node('p','Only the chat’s name and type are shown here. Approving admits it as a CRM conversation source. It creates no Work.','muted'));
 const opts={buttons:[['approve','Admit chat','primary'],['reject','Reject']],refresh:()=>loadStore('intake',true),run:async(action,reason,key)=>{await api('/api/board/approvals/intake/'+i.id+'/decision',json('POST',{action,reason:reason||(action==='approve'?'Admitted in Approvals':'Rejected in Approvals'),idempotencyKey:key}));Q.intake.rows=Q.intake.rows.filter(x=>x.id!==i.id);return action==='approve'?'Admitted “'+(i.title||'chat')+'”. No Work was created.':'Rejected “'+(i.title||'chat')+'”.';}};
 summary.append(quickBar(card,opts));body.append(decideBlock(card,opts));card.append(body);return card;}
/* Bulk decisions: every item in the current tab that has a plain approve/reject, decided one by one with its own key. */
function bulkItems(){const out=[],proposal=p=>out.push({id:p.id,name:p.display_name||'Relationship',url:'/api/board/approvals/proposals/'+p.id+'/decision',store:'proposals'});
 if(tab==='placement'){for(const r of Q.placements.rows){const p=stageProposalFor(r.id);if(p)proposal(p);}}
 else if(tab==='changes'){for(const p of tabItems('changes'))proposal(p);}
 else if(tab==='work'){for(const p of Q.proposals.rows.filter(isWorkProposal))proposal(p);for(const w of Q.work.rows)out.push({id:w.id,name:w.display_name||'Work item',url:'/api/board/approvals/work/'+w.id+'/decision',store:'work'});}
 else for(const i of Q.intake.rows)out.push({id:i.id,name:i.title||'Chat',url:'/api/board/approvals/intake/'+i.id+'/decision',store:'intake'});
 return out;}
async function bulkDecide(action){const items=bulkItems(),t=tabs.find(x=>x.id===tab),verb=action==='approve'?'Approve':'Reject';
 if(!items.length||!confirm(verb+' all '+items.length+' item'+(items.length===1?'':'s')+' in “'+t.label+'”? Each decision is applied immediately.'))return;
 const bar=el('bulk');for(const b of bar.querySelectorAll('button'))b.disabled=true;const failed=[],touched=new Set(),done=new Set();
 for(const it of items){try{await api(it.url,json('POST',{action,reason:(action==='approve'?'Approved':'Rejected')+' in bulk in Approvals',idempotencyKey:crypto.randomUUID()}));done.add(it.id);}catch(error){failed.push(it.name+': '+error.message);}touched.add(it.store);}
 for(const n of touched)Q[n].rows=Q[n].rows.filter(r=>!done.has(r.id));
 notice(verb+'d '+done.size+(failed.length?' · '+failed.length+' failed — '+failed.slice(0,3).join('; ')+(failed.length>3?'…':''):''),failed.length>0);
 await Promise.all([...touched,...(touched.has('proposals')?['placements']:[])].map(n=>loadStore(n,true)));}
function renderBulk(){const bar=el('bulk'),items=bulkItems();bar.replaceChildren();bar.hidden=!items.length;if(!items.length)return;
 const actions=node('div',undefined,'actions'),ok=node('button','Approve all ('+items.length+')','primary'),no=node('button','Reject all ('+items.length+')');ok.type=no.type='button';ok.onclick=()=>void bulkDecide('approve');no.onclick=()=>void bulkDecide('reject');actions.append(ok,no);
 bar.append(node('p','Decide everything in this tab at once. Items that need a stage chosen are skipped.','muted'),actions);}
const empties={placement:'Nothing is waiting for an initial stage. New relationships appear here until someone places them.',changes:'No CRM changes are waiting for a decision.',work:'No Work tickets or lane moves are waiting for a decision.',intake:'No chats are waiting for admission.'};
function renderQueue(){const t=tabs.find(x=>x.id===tab),box=el('queue');box.replaceChildren();
 const failed=t.stores.filter(n=>Q[n].error);for(const n of failed){const row=node('div',undefined,'notice');row.dataset.error='true';row.append(node('span',Q[n].error+' '));const again=node('button','Retry');again.type='button';again.onclick=()=>void loadStore(n,true);row.append(again);box.append(row);}
 if(t.stores.some(n=>!Q[n].loaded)){el('bulk').hidden=true;box.append(node('div',undefined,'skeleton'),node('div',undefined,'skeleton'));return;}
 const groups=t.id==='work'?[['Work tickets proposed from CRM',Q.proposals.rows.filter(isWorkProposal).map(p=>proposalCard(p)),'proposals'],['Lane moves',Q.work.rows.map(workCard),'work']]:[[null,tabItems(t.id).map(x=>t.id==='placement'?placementCard(x):t.id==='changes'?proposalCard(x):intakeCard(x)),t.stores.find(n=>n!=='proposals')||'proposals']];
 let any=false;for(const [heading,cards,store] of groups){if(cards.length){any=true;if(heading&&groups.every(g=>g[1].length))box.append(node('h3',heading,'group'));box.append(...cards);}if(Q[store].cursor){const more=node('button','Load more','more');more.type='button';more.onclick=()=>{more.disabled=true;void loadStore(store,false);};box.append(more);any=true;}}
 if(t.id==='placement'&&Q.proposals.cursor){const more=node('button','Load more suggestions','more');more.type='button';more.onclick=()=>{more.disabled=true;void loadStore('proposals',false);};box.append(more);}
 if(!any&&!failed.length)box.append(node('p',empties[t.id],'empty'));renderBulk();}
async function start(){try{member=(await api('/api/session')).member;mountTopbar(member);ticketPanel=createTicketPanel({member,onChange:async()=>{for(const [key,f]of Object.entries(feeds))if(key!==source)f.loaded=false;await load(true);if(mode==='dashboard')await loadSummary();}});
 if(mode==='team'){if(member.role!=='admin'){location.replace('/dashboard');return;}el('title').textContent='Workspace access';el('description').textContent='Choose who can manage CRM, keep tasks, or only read.';el('team').hidden=false;for(const id of ['toolbar','board','stage-nav'])el(id).hidden=true;await loadMembers();notice('Role and access changes apply on the person’s next request.');return;}
 if(mode==='approvals'){if(!canReview()){location.replace('/dashboard');return;}el('title').textContent='Approvals';el('description').textContent='Decide what is waiting: new relationships, changes to existing ones, and Work. Decisions here and in Telegram act on the same records.';el('approvals').hidden=false;for(const id of ['toolbar','board','stage-nav','more'])el(id).hidden=true;el('queue-refresh').onclick=()=>void loadAll();renderTabs();await loadAll();const first=tabs.find(t=>(!t.admin||member.role==='admin')&&tabItems(t.id).length);if(first&&!tabItems(tab).length){tab=first.id;renderTabs();renderQueue();}notice('');return;}
 const viewer=member.role==='viewer';
 if(mode==='work'){el('title').textContent='My tasks';el('description').textContent=viewer?'You have read-only access. Browse team tasks from the scope menu.':'Your personal tasks and assigned CRM Work, together in one place.';el('scope-label').hidden=false;el('create-task').hidden=viewer;if(viewer){source='team';el('title').textContent='Team tasks';el('scope').querySelector('option[value=mine]').remove();el('scope').value='team';}}
 else{el('title').textContent='Team overview';el('mode-tag').hidden=member.role!=='viewer';el('description').textContent='Open a ticket to inspect its context, sources, and next steps.';el('view').hidden=false;el('crm-link').hidden=false;el('crm-link').textContent=['admin','crm_manager'].includes(member.role)?'Manage CRM':'Open CRM';void loadSummary();}
 await load(true);}catch(error){notice(error.message,true);}}
void start();
</script></body></html>`;
